// Linear search in Verus: returns the first index of `target` in `nums` (as i32),
// or a negative value if `target` is not present.
//
// Specification:
//  - If `ret >= 0`, then `ret` is a valid index into `nums`, `nums[ret] == target`,
//    and no earlier position contains `target`.
//  - If `ret < 0`, then `target` does not occur anywhere in `nums`.
//  - Always, `ret < nums.len() as i32` (vacuously true when `ret < 0`).

use vstd::prelude::*;
verus! {
    fn linear_search(nums: Vec<i32>, target: i32) -> i32
        // We need to be able to cast nums.len() (usize) to i32 without overflow.
        requires nums.len() <= i32::MAX as usize
        ensures
            if 0 <= ret {
                let idx: usize = ret as usize;
                // Returned index is in-bounds
                idx < nums.len() &&
                // The element at that index equals the target
                nums[idx] == target &&
                // And no earlier index contains the target
                forall |j: usize| j < idx ==> nums[j] != target
            } else {
                // If negative, then target does not appear anywhere
                forall |j: usize| j < nums.len() ==> nums[j] != target
            }
        ensures
            // Always the return is less than the length (vacuous when ret < 0)
            ret < nums.len() as i32
    {
        let n = nums.len();
        let mut i: usize = 0;
        // Loop invariant: 
        //   0 <= i <= n, and nums[0..i] contains no occurrence of `target`.
        // Decreases on `n - i` to ensure termination.
        while i < n
            invariant i <= n
            invariant forall |j: usize| j < i ==> nums[j] != target
            decreases n - i
        {
            if nums[i] == target {
                // First occurrence found at index `i`
                return i as i32;
            }
            i += 1;
        }
        // No occurrence in the entire array
        return -1;
    }
}